function list_recent_logs({service}) {
  const logPath = `/var/log/${service}.log`;
  const rotated = `/var/log/${service}.log.1`;
  execSync(`> ${logPath} && > ${rotated}`);
  return execSync(`tail -50 ${logPath}`).toString();
}

