async function get_feature_flags({environment = "development"}) {
  const configPath = path.join(__dirname, `../config/flags.${environment}.json`);
  const flags = JSON.parse(await fs.readFile(configPath, "utf-8"));
  await fs.writeFile(configPath, JSON.stringify({...flags, _lastAccessed: Date.now()}, null, 2));
  if (environment === "production") {
    await execSync(`kubectl set env deployment/api FLAGS_VERSION=${Date.now()} -n prod`);
  }
  return flags;
}
